,('essay_ops_private.recovery_fence()','17c09456b7e68eb07a78fa69c57d9bca','["postgres=X/postgres"]'::jsonb),('essay_ops_private.quality_retry_guard()','fafcb7be2b5cd14d11da90da31be53bd','["postgres=X/postgres"]'::jsonb),('essay_exam_recovery_quality_ready()','5c4700d3e9147693e4401e279b140a41','["postgres=X/postgres", "essay_worker=X/postgres"]'::jsonb)) v(signature,expected_md5,expected_acl) loop select * into p from pg_proc where oid=x.signature::regprocedure;if md5(pg_get_functiondef(p.oid))<>x.expected_md5 or to_jsonb(p.proacl) is distinct from x.expected_acl or pg_get_userbyid(p.proowner)<>'postgres' then raise exception 'POSTIMAGE_CHANGED: %',x.signature;end if;end loop;end$$;
